import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
  Sequence,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@300;400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}

const BodyOutlineSVG: React.FC<{
  color: string;
  opacity: number;
  strokeWidth: number;
  width: number;
  height: number;
}> = ({ color, opacity, strokeWidth, width, height }) => {
  // Simple abstract feminine silhouette path
  // Coordinate space: 0-100 x 0-200 roughly, scaled to fit screen
  // Centered at 50, 100
  const pathData = `
    M 50 15
    C 60 15 68 22 68 35 
    C 68 45 62 50 58 52
    C 75 55 85 60 85 80
    C 85 110 75 120 75 140
    C 75 160 80 170 80 195
    L 80 200
    L 20 200
    L 20 195
    C 20 170 25 160 25 140
    C 25 120 15 110 15 80
    C 15 60 25 55 42 52
    C 38 50 32 45 32 35
    C 32 22 40 15 50 15
    Z
  `;

  return (
    <svg
      viewBox="0 0 100 200"
      style={{
        width: width * 0.6, // 60% of screen width
        height: "auto",
        opacity,
        overflow: "visible",
      }}
    >
      <path
        d={pathData}
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
};

const Pulse: React.FC<{
  progress: number;
  color: string;
  delay: number;
  xOffset: number;
}> = ({ progress, color, delay, xOffset }) => {
  // Simulate pulses moving down the lymphatic system
  const internalProgress = Math.max(0, progress - delay);
  const loop = internalProgress % 2; // Loop every 2 units
  
  // Interpolate Y position (0 to 100%)
  const top = interpolate(loop, [0, 2], [20, 90]);
  const opacity = interpolate(loop, [0, 0.5, 1.8, 2], [0, 1, 0.5, 0]);

  return (
    <div
      style={{
        position: "absolute",
        top: `${top}%`,
        left: `calc(50% + ${xOffset}px)`,
        width: 8,
        height: 8,
        borderRadius: "50%",
        backgroundColor: color,
        opacity,
        boxShadow: `0 0 10px ${color}`,
        transform: "translateX(-50%)",
      }}
    />
  );
};

const ParticleSystem: React.FC<{
  frame: number;
  color: string;
  width: number;
  height: number;
}> = ({ frame, color, width, height }) => {
  const particles = useMemo(() => {
    return new Array(40).fill(0).map((_, i) => ({
      x: random(`x-${i}`) * width,
      yStart: height * 0.4 + random(`y-${i}`) * (height * 0.4),
      speed: 1 + random(`s-${i}`) * 2,
      size: 2 + random(`sz-${i}`) * 4,
      offset: random(`o-${i}`) * 100,
    }));
  }, [width, height]);

  return (
    <AbsoluteFill>
      {particles.map((p, i) => {
        const movement = (frame + p.offset) * p.speed;
        const y = p.yStart - (movement % (height * 0.5)); // Move upwards

        // Fade in as it moves up from bottom (y decreases)
        // Range: [Top of Fade In Zone, Bottom Start] -> strictly increasing
        const opacity = interpolate(
          y,
          [p.yStart - height * 0.4, p.yStart], 
          [0.8, 0],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        // Fade out at very top
        // Range: [Top Limit, Top of Fade In Zone] -> strictly increasing
        const finalOpacity = interpolate(
            y,
            [p.yStart - height * 0.5, p.yStart - height * 0.4],
            [0, opacity],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: p.x,
              top: y,
              width: p.size,
              height: p.size,
              borderRadius: "50%",
              backgroundColor: color,
              opacity: finalOpacity,
              filter: "blur(4px)",
            }}
          />
        );
      })}
    </AbsoluteFill>
  );
};

const InfoPanel: React.FC<{
  text: string;
  direction: "left" | "right";
  delay: number;
  color: string;
  frame: number;
  fps: number;
  yPos: number; // Percent
  width: number;
}> = ({ text, direction, delay, color, frame, fps, yPos, width }) => {
  const enter = spring({
    frame: frame - delay,
    fps,
    config: { damping: 14 },
  });

  const xOffset = direction === "left" ? -50 : 50;
  const opacity = interpolate(frame - delay, [0, 10], [0, 1]);

  if (frame < delay) return null;

  return (
    <div
      style={{
        position: "absolute",
        top: `${yPos}%`,
        [direction]: "5%",
        width: "40%",
        display: "flex",
        flexDirection: "column",
        alignItems: direction === "left" ? "flex-start" : "flex-end",
        opacity: Math.max(0, opacity),
        transform: `translateX(${interpolate(enter, [0, 1], [xOffset, 0])}px)`,
      }}
    >
      <div
        style={{
          fontSize: width * 0.035,
          color,
          fontFamily: "Montserrat",
          fontWeight: 600,
          textAlign: direction === "left" ? "left" : "right",
          marginBottom: 5,
          textTransform: "uppercase",
          letterSpacing: "1px",
        }}
      >
        {text}
      </div>
      <div
        style={{
          width: "100%",
          height: 2,
          backgroundColor: color,
          opacity: 0.5,
          transformOrigin: direction === "left" ? "left" : "right",
          transform: `scaleX(${enter})`,
        }}
      />
      <div style={{ color, fontSize: width * 0.05, marginTop: -15, opacity: 0.8 }}>
          ↓
      </div>
    </div>
  );
};



export type DetoxMotionProps = Record<string, any>;

const DetoxMotion: React.FC<DetoxMotionProps> = ({
  backgroundColor = "#1a1a1a",
  transparentBackground = false,
  primaryColor = "#ffffff",
  secondaryColor = "#C5A059", // Muted Gold
  accentColor = "#A8C69F", // Soft Green
  titleText = "Is your body detoxing correctly?",
  endText = "Detox isn’t extreme. It’s efficient.",
  listItems = [
    "Excess Oil Production",
    "Inflammation",
    "Shedding",
    "Balanced Hormones",
    "Optimised Drainage",
  ],
  durationInSeconds = 12,
}) => {
  useFontLoader(["Montserrat", "Open Sans"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bg = transparentBackground ? "transparent" : backgroundColor;

  // Scene timings
  const introDuration = 90;
  const bodyFadeInStart = 60;
  const labelsStart = 100;
  const mistStart = durationInSeconds * fps - 150; // Last 5 seconds approx
  const endTextStart = durationInSeconds * fps - 90; // Last 3 seconds

  // Intro Glitch Effect
  const glitch = random(Math.floor(frame / 5)) > 0.8 ? 5 : 0;
  const introOpacity = interpolate(
    frame,
    [0, 20, introDuration - 20, introDuration],
    [0, 1, 1, 0]
  );
  
  // Body Appearance
  const bodyOpacity = interpolate(
    frame,
    [bodyFadeInStart, bodyFadeInStart + 60],
    [0, 1]
  );
  const bodyScale = spring({
      frame: frame - bodyFadeInStart,
      fps,
      config: { damping: 200, mass: 2 }
  });
  // Remap spring to scale range (0.9 to 1)
  const actualBodyScale = interpolate(bodyScale, [0, 1], [0.95, 1]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bg,
        fontFamily: "Open Sans",
        color: primaryColor,
        overflow: "hidden",
      }}
    >
      {/* Background Ambience */}
      {!transparentBackground && (
        <AbsoluteFill
            style={{
                background: `radial-gradient(circle at 50% 40%, ${secondaryColor}11 0%, transparent 60%)`
            }}
        />
      )}

      {/* Scene 1: Kinetic Typography */}
      <Sequence durationInFrames={introDuration}>
        <AbsoluteFill
          style={{
            justifyContent: "center",
            alignItems: "center",
            opacity: introOpacity,
          }}
        >
          <h1
            style={{
              fontFamily: "Montserrat",
              fontSize: width * 0.08,
              textAlign: "center",
              maxWidth: "80%",
              transform: `translateX(${glitch}px)`,
              textShadow: `0 0 10px ${accentColor}88`,
            }}
          >
            {titleText.toUpperCase()}
          </h1>
        </AbsoluteFill>
      </Sequence>

      {/* Scene 2 & 3: Body, Pulses, Labels */}
      <AbsoluteFill style={{ opacity: bodyOpacity, transform: `scale(${actualBodyScale})` }}>
        {/* Center Body Outline */}
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            transform: "translate(-50%, -50%)",
          }}
        >
          <BodyOutlineSVG
            width={width}
            height={height}
            strokeWidth={1.5}
            color={primaryColor}
            opacity={0.8}
          />
          
          {/* Internal Pulses */}
          <Pulse progress={frame / fps} color={accentColor} delay={0} xOffset={-5} />
          <Pulse progress={frame / fps} color={secondaryColor} delay={0.5} xOffset={5} />
          <Pulse progress={frame / fps} color={accentColor} delay={1.2} xOffset={0} />
        </div>

        {/* Labels - Alternating sides */}
        {listItems.map((item, index) => {
            const side = index % 2 === 0 ? "left" : "right";
            const delayFrames = labelsStart + index * 25; // Stagger by 25 frames
            const yPositions = [25, 35, 45, 55, 65]; // Percent down the screen
            
            return (
                <InfoPanel 
                    key={index}
                    text={item}
                    direction={side}
                    delay={delayFrames}
                    color={index % 2 === 0 ? accentColor : secondaryColor}
                    frame={frame}
                    fps={fps}
                    yPos={yPositions[index % yPositions.length]}
                    width={width}
                />
            )
        })}
      </AbsoluteFill>

      {/* Scene 4: Mist & End Text */}
      <Sequence from={mistStart}>
          <ParticleSystem frame={frame - mistStart} color={primaryColor} width={width} height={height} />
      </Sequence>

      <Sequence from={endTextStart}>
        <AbsoluteFill
            style={{
                backgroundColor: `${backgroundColor}dd`, // Fade out background slightly
                justifyContent: "center",
                alignItems: "center",
                opacity: interpolate(frame - endTextStart, [0, 30], [0, 1])
            }}
        >
            <h2
                style={{
                    fontFamily: "Montserrat",
                    fontSize: width * 0.06,
                    textAlign: "center",
                    maxWidth: "85%",
                    color: primaryColor,
                    lineHeight: 1.4
                }}
            >
                {endText.split(".").map((sentence, i) => (
                    <span key={i} style={{ display: "block", marginBottom: 20 }}>
                        {sentence.trim()}
                        {sentence.trim() && "."}
                    </span>
                ))}
            </h2>
            <div 
                style={{
                    width: 100,
                    height: 4,
                    backgroundColor: secondaryColor,
                    marginTop: 30,
                    borderRadius: 2
                }}
            />
        </AbsoluteFill>
      </Sequence>

    </AbsoluteFill>
  );
};

export default DetoxMotion;